// === Tab: mySketch ===
var ring = [];
var points = 200;

var layers = 25;

function setup() { 
  createCanvas(600, 600);

  for (var a=0; a<layers; a++){
    var layerpoints = [];
  	  for (var i=0; i<points; i++){
  			var rad = 280 - a*5;
        layerpoints.push({ radius: rad, angle: (TWO_PI*i/points) });
  	 }	
    ring.push(layerpoints);
  }
} 

function draw() { 
  background(255);
  translate(300,300);
  noStroke();
  for (var a=0; a<layers; a++){
   // fill(255,235-(a*2),200-(a*10),(a*a)/4);
    stroke(120 + (a)*4);
    //stroke(255);
    beginShape();
  	  for (var i=0; i<points; i++){
        xp = ring[a][i].radius*cos(ring[a][i].angle);
        yp = ring[a][i].radius*sin(ring[a][i].angle);
        vertex(xp,yp);
  	 }	
    endShape(CLOSE);
  }
	deform();

}

function deform(){
  for (var a=1; a<layers; a++){

  	  for (var i=0; i<points; i++){
        xp = ring[a][i].radius*cos(ring[a][i].angle);
        yp = ring[a][i].radius*sin(ring[a][i].angle);       
        ring[a][i].radius = ring[a-1][i].radius - noise((frameCount/2+xp)/100,(frameCount/2+yp)/100)*(a*1.2);   
  	 }	
  }
}
